-- Scale gates are fail-closed. Unknown is not treated as pass.
SELECT *
FROM (
  VALUES
    ('ios_crash_gate', 'iOS crash gate', 'blocked', 'Authenticated App Store Connect confirms one iOS 1.0.1 crash on 2026-08-25, but privacy suppression exposes no device, OS, crash report, stack, or UUID. Xcode Organizer also reports that a developer account is required to download the crash list, so symbolication and root-cause verification remain blocked.', 'Restore Organizer developer-account access or obtain the diagnostic report, then symbolicate, reproduce, fix, and re-smoke'),
    ('open_meteo_promotion_clearance', 'Open-Meteo promotion clearance', 'pending', 'Clarification was sent to Open-Meteo''s official contact at 2026-08-29 06:05 +05:00 from the authenticated maintainer account; no written reply has been received.', 'Monitor the sent thread and record an unambiguous written response'),
    ('release_artifact_source_sync', 'Release artifact source sync', 'blocked', 'Android phone 1.1.0 (8) and Apple 1.1.0 (6) are the current source identities. The exact-HEAD unsigned phone AAB validates and current debug bytes pass bounded device QA, but Android Keychain value lookups exit with status 51; Apple archive codesign fails with errSecInternalComponent backed by errSecAuthFailed. There is no upload-signed phone AAB, signed Apple archive, or matching signed-artifact physical QA; unchanged Wear OS 1.1.0 (1000008) alone remains verified-current. See growth/quality/signing-readiness-2026-08-29.md.', 'Restore private signing authorization without replacing the existing identities, then create new signed vc8 and build-6 artifacts, verify identities and hashes, and record exact physical QA'),
    ('android_physical_smoke', 'Android device smoke', 'blocked', 'Commit 80cdd60 phone 1.1.0 (8) passed a matching-byte current-source debug smoke on a physical API 25 phone and API 36 emulator, including legacy navigation contrast, IME resize, landscape side-cutout insets, true offline cache, recovery, sharing, and process stability. There is still no upload-signed vc8 or release-certificate physical result, and physical tablet, widget, and Wear OS coverage remains required.', 'Sign and verify phone vc8, then run the exact signed artifact on phone and tablet plus widget and paired Wear OS paths'),
    ('ios_physical_smoke', 'iOS physical smoke', 'blocked', 'Current Apple 1.1.0 (6) source changes the foreground review-request path, durable automatic-refresh state, saved-location cleanup, repository observation windows, and all-side safe-drawing insets. It has no distribution-signed archive, artifact hash, or matching physical result. A current iPad now has a compatible usable DDI and connected tunnel, but signing blocks installation; current iPhone, iPad, widget, and watch coverage remains required.', 'Archive and distribution-sign build 6, then run the exact artifact on iPhone and iPad plus widget and paired watch paths'),
    ('domain_activation', 'Domain activation', 'blocked', 'The registrar surface reports nimbo.uz is activating and domain-specific WHOIS reports EXPIRED with creation and expiration both 2026-08-28; the apparent top-level ACTIVE line belongs to the IANA .UZ ccTLD object, not NIMBO.UZ. Cloudflare remains pending, but both assigned child nameservers authoritatively serve the complete DNS-only GitHub Pages record set. Registry authorities and public resolvers still return DNSSEC-validated NXDOMAIN, so parent delegation and TLS remain absent.', 'Wait for registrar activation, verify registry delegation and the staged records from independent resolvers, then wait for valid HTTPS'),
    ('store_policy_console_clearance', 'Store policy console clearance', 'pass', 'The 2026-08-28 App Store read-only check found no open review/compliance action, and the authenticated Google Play recheck at 2026-08-29 06:24 +05:00 again explicitly reported no policy issues and no pending publishing change. See growth/quality/store-policy-console-2026-08-28.md.', 'Re-check both store policy surfaces with the next weekly UZ console evidence window')
) AS gates(gate_id, gate, status, evidence, next_action);
